import { Match as M, Option, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Tooltip from "../../ui/shadcn-tooltip";

// MODEL

export const Model = S.Struct({
  tooltip: Tooltip.Model,
  status: S.String,
});
export type Model = typeof Model.Type;

// MESSAGE

export const GotTooltipMessage = m("GotTooltipMessage", {
  message: Tooltip.Message,
});

export const Message = S.Union([GotTooltipMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [tooltip, commands] = Tooltip.init({ id: "tooltip-basic" });

  return [
    { tooltip, status: "Tooltip hidden." },
    Command.mapMessages(commands, (message) => GotTooltipMessage({ message })),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotTooltipMessage: ({ message }) => {
        const [tooltip, commands, maybeOutMessage] = Tooltip.update(
          model.tooltip,
          message
        );
        const status = Option.match(maybeOutMessage, {
          onNone: () => model.status,
          onSome: M.type<Tooltip.OutMessage>().pipe(
            M.tagsExhaustive({
              Hidden: () => "Tooltip hidden.",
              Shown: () => "Tooltip shown.",
            })
          ),
        });

        return [
          evo(model, { tooltip: () => tooltip, status: () => status }),
          Command.mapMessages(commands, (message) =>
            GotTooltipMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-4")],
    [
      h.submodel({
        slotId: model.tooltip.id,
        model: model.tooltip,
        view: Tooltip.view,
        viewInputs: {
          anchor: Tooltip.tooltipAnchor,
          toView: (render) =>
            Tooltip.tooltipView({
              render,
              triggerLabel: "Hover",
              panelText: "Add to library",
            }),
        },
        toParentMessage: (message) => GotTooltipMessage({ message }),
      }),
      h.div(
        [h.Class("flex flex-wrap gap-2")],
        [
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["left"]
          ),
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["top"]
          ),
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["bottom"]
          ),
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["right"]
          ),
        ]
      ),
      h.button(
        [h.Type("button"), h.Class(`${Tooltip.tooltipTriggerClassName} gap-2`)],
        [
          h.span([], ["Save"]),
          h.span(
            [h.Class("rounded bg-gray-100 px-1.5 py-0.5 text-xs")],
            ["⌘S"]
          ),
        ]
      ),
      h.span(
        [
          h.Class(
            "inline-flex cursor-not-allowed rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-400"
          ),
        ],
        ["Disabled"]
      ),
      h.div(
        [h.Dir("rtl"), h.Class("flex flex-wrap gap-2")],
        [
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["يسار"]
          ),
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["أعلى"]
          ),
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["أسفل"]
          ),
          h.button(
            [h.Type("button"), h.Class(Tooltip.tooltipTriggerClassName)],
            ["يمين"]
          ),
        ]
      ),
      h.p([h.Class("text-sm text-gray-700")], [model.status]),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Tooltip from "../../ui/shadcn-tooltip";
import * as TooltipBasicExample from "./main";

const toParentMessage = (message: Tooltip.Message) =>
  TooltipBasicExample.GotTooltipMessage({ message });

const AnchorTooltip = Tooltip.AnchorTooltip({
  buttonId: "tooltip-basic-trigger",
  anchor: Tooltip.tooltipAnchor,
});

const resolveTooltipMount = () =>
  Scene.Mount.resolve(
    AnchorTooltip,
    Tooltip.CompletedAnchorTooltip(),
    toParentMessage
  );

describe("shadcn Tooltip Basic example", () => {
  test("shows tooltip content after hover delay", () => {
    const [initialModel] = TooltipBasicExample.init();

    Scene.scene(
      {
        update: TooltipBasicExample.update,
        view: TooltipBasicExample.view,
      },
      Scene.with(initialModel),
      Scene.expect(Scene.text("Add to library")).not.toExist(),
      Scene.expect(Scene.role("button", { name: "left" })).toExist(),
      Scene.expect(Scene.role("button", { name: "top" })).toExist(),
      Scene.expect(Scene.role("button", { name: "bottom" })).toExist(),
      Scene.expect(Scene.role("button", { name: "right" })).toExist(),
      Scene.expect(Scene.text("Save")).toExist(),
      Scene.expect(Scene.text("⌘S")).toExist(),
      Scene.expect(Scene.text("Disabled")).toExist(),
      Scene.expect(Scene.role("button", { name: "يسار" })).toExist(),
      Scene.hover(Scene.role("button", { name: "Hover" })),
      Scene.Command.resolve(
        Tooltip.ShowAfterDelay({
          delay: initialModel.tooltip.showDelay,
          version: 1,
        }),
        Tooltip.ElapsedShowDelay({ version: 1 }),
        toParentMessage
      ),
      resolveTooltipMount(),
      Scene.expect(Scene.role("tooltip")).toExist(),
      Scene.expect(Scene.text("Add to library")).toExist(),
      Scene.expect(Scene.text("Tooltip shown.")).toExist()
    );
  });
});
